                # strip string literals and comments
                bare = re.sub(r'"[^"]*"', '""', line)
                bare = re.sub(r'\(\*.*?\*\)', '', bare)
                for m in re.finditer(r'(?<![0-9A-Za-z_.])([0-9]{9,30})(?![0-9A-Za-z_])', bare):
